// LessonContent.tsx
import React, {useState} from 'react';
import {View, TouchableOpacity} from 'react-native';
import MIcon from 'react-native-vector-icons/MaterialIcons';
import {MainStackParamList} from '../../navigation/MainNavigator';
import {buildLink, useAuthStore} from '@smarttestpro/smart-common';
import {NativeStackScreenProps} from '@react-navigation/native-stack';
import {ActivityIndicator, Button, Text, useTheme} from 'react-native-paper';
import WebView from 'react-native-webview';
type Props = NativeStackScreenProps<
  MainStackParamList,
  'WebviewDetailExamResultScreen'
>;

const WebviewDetailExamResultScreen = ({navigation, route}: Props) => {
  const {accessToken, refreshToken} = useAuthStore();
  const [error, setError] = useState(false);
  const theme = useTheme();
  const [loading, setLoading] = useState(false);

  const [renderKey, setRenderKey] = useState(Date.now());
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [showURI, setShowURI] = useState(false);

  const baseUrl = 'https://smarttest.pro';
  const url = `/${buildLink(
    `webview/testdetail/${route.params.testResultId}`,
    {},
  )}`;
  const uri = route.params.testResultId
    ? `${baseUrl}/thanh-vien/dang-nhap?return_to=${encodeURI(
        url,
      )}&accessToken=${encodeURI(accessToken || '')}&refreshToken=${encodeURI(
        refreshToken || '',
      )}`
    : null;

  if (!uri) {
    return (
      <View>
        <Text>Vui lòng xem lại, kết quả thi không tồn tại!</Text>
      </View>
    );
  }

  if (error) {
    return (
      <View
        style={{
          flex: 1,
          padding: 24,
          gap: 20,
          justifyContent: 'center',
          alignItems: 'center',
        }}>
        <Text variant="bodyLarge" style={{textAlign: 'center'}}>
          Có lỗi xảy ra, vui lòng kiểm tra mạng và bấm nút "Tải lại trang"!
        </Text>
        {showURI === true && <Text style={{textAlign: 'center'}}>{uri}</Text>}
        <Button
          mode="contained"
          onLongPress={() => {
            // setShowURI(!showURI);
          }}
          onPress={() => {
            setRenderKey(Date.now());
            setLoading(true);
            setError(false);
          }}>
          Tải lại trang
        </Button>
      </View>
    );
  }

  return (
    <View className="flex-1 bg-gray-50">
      {/* Header */}
      <View className="bg-white shadow-sm">
        {/* Top Navigation Bar */}
        <View
          className={`h-10 bg-[${theme.colors.primaryContainer}] flex-row items-center px-2`}>
          <TouchableOpacity onPress={() => navigation.goBack()}>
            <View className="px-1 h-10 justify-center">
              <MIcon name="arrow-back" size={24} />
            </View>
          </TouchableOpacity>
          <View className="flex-1 items-center mr-2">
            <Text className="text-lg font-bold text-gray-800">
              Chi tiết kết quả bài thi
            </Text>
          </View>
        </View>

        {/* <View className="flex-row items-center justify-end px-4 py-2 border-t border-gray-100">
          <TouchableOpacity
            onPress={handleDecreaseFontSize}
            className="w-8 h-8 items-center justify-center rounded-full bg-gray-100">
            <MaterialIcons name="text-decrease" size={20} color="#4b5563" />
          </TouchableOpacity>
          <TouchableOpacity
            onPress={handleIncreaseFontSize}
            className="w-8 h-8 items-center justify-center rounded-full bg-gray-100 ml-2">
            <MaterialIcons name="text-increase" size={20} color="#4b5563" />
          </TouchableOpacity>
        </View> */}
      </View>

      <View style={{flex: 1, backgroundColor: '#fff'}}>
        {loading === true && (
          <View style={{padding: 20}}>
            <ActivityIndicator animating={true} />
          </View>
        )}
        <View className="flex-1 pb-2">
          <WebView
            originWhitelist={['*']}
            javaScriptEnabled
            domStorageEnabled
            onError={() => {
              setError(true);
              return (
                <View>
                  <Text>
                    Có lỗi xảy ra, vui lòng kiểm tra mạng và bấm nút "Tải lại
                    trang"!
                  </Text>
                </View>
              );
            }}
            onLoad={() => setLoading(false)}
            key={renderKey}
            cacheEnabled={true}
            onReceivedError={() => {
              return (
                <View>
                  <Text>
                    Có lỗi xảy ra, vui lòng kiểm tra mạng và bấm nút "Tải lại
                    trang"!
                  </Text>
                </View>
              );
            }}
            startInLoadingState={true}
            // renderLoading={() => <ActivityIndicator animating={true} />}
            renderError={() => {
              return (
                <View>
                  <Text>
                    Có lỗi xảy ra, vui lòng kiểm tra mạng và bấm nút "Tải lại
                    trang"!
                  </Text>
                </View>
              );
            }}
            source={{
              uri,
            }}
            style={{flex: 1}}
          />
        </View>
      </View>
    </View>
  );
};

export default WebviewDetailExamResultScreen;
